CREATE COLUMN TABLE "TEST_AP"."@UTILSQL" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_Pwd" NCLOB MEMORY THRESHOLD 1000, "U_User" NCLOB MEMORY THRESHOLD 1000, "U_Server" NCLOB MEMORY THRESHOLD 1000, "U_TEST" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KUTILSQL_NAME" ON "TEST_AP"."@UTILSQL" ( "Name" ASC )